-- Navigation between .proto definitions and the ScalaPB/protoc-java code generated from them.
local M = {}

local GENERATED_MARKERS = {
  "Generated by the Scala Plugin for the Protocol Buffer Compiler",
  "Generated by the protocol buffer compiler",
}

---@param lines string[]
local function is_generated(lines)
  local head = table.concat(lines, "\n", 1, math.min(#lines, 5))
  for _, marker in ipairs(GENERATED_MARKERS) do
    if head:find(marker, 1, true) then
      return true
    end
  end
  return false
end

---@param lines string[]
local function package_of(lines)
  for _, l in ipairs(lines) do
    local pkg = l:match("^%s*package%s+([%w_%.]+)")
    if pkg then
      return pkg
    end
  end
end

---@param buf integer
function M.buf_is_generated(buf)
  return is_generated(vim.api.nvim_buf_get_lines(buf, 0, 5, false))
end

local function read_head(path, n)
  local buf = vim.fn.bufnr(path)
  if buf > 0 and vim.api.nvim_buf_is_loaded(buf) then
    return vim.api.nvim_buf_get_lines(buf, 0, n, false)
  end
  local ok, lines = pcall(vim.fn.readfile, path, "", n)
  return ok and lines or {}
end

local function snake(s)
  return (s:gsub("(%l)(%u)", "%1_%2"):gsub("(%u)(%u%l)", "%1_%2"):lower())
end

local function pascal(s)
  return s:sub(1, 1):upper() .. s:sub(2)
end

local ACCESSOR_PREFIXES = { "addAll", "putAll", "with", "get", "set", "has", "clear", "add", "put", "remove" }
local ACCESSOR_SUFFIXES = { "OrBuilderList", "OrBuilder", "List", "Count", "Map", "Value", "Bytes" }

-- Generated identifier -> proto names it may come from.
---@return { types: string[], fields: string[] }
function M.proto_names(word)
  local types = { word, pascal(word) }
  local base = word:gsub("Grpc$", ""):gsub("Proto$", "")
  if base ~= word and base ~= "" then
    table.insert(types, base)
  end

  local fields = { word, snake(word) }
  local stems = { word }
  for _, p in ipairs(ACCESSOR_PREFIXES) do
    local rest = word:match("^" .. p .. "(%u.*)$")
    if rest then
      table.insert(stems, rest)
    end
  end
  for _, stem in ipairs(vim.list_slice(stems)) do
    for _, s in ipairs(ACCESSOR_SUFFIXES) do
      local rest = stem:match("^(.+)" .. s .. "$")
      if rest then
        table.insert(stems, rest)
      end
    end
  end
  for _, stem in ipairs(stems) do
    table.insert(fields, snake(stem))
  end
  return { types = vim.fn.uniq(vim.fn.sort(types)), fields = vim.fn.uniq(vim.fn.sort(fields)) }
end

local function alternation(names)
  return "(" .. table.concat(names, "|") .. ")"
end

---@class understand.ProtoMatch
---@field file string
---@field lnum integer
---@field col integer
---@field text string
---@field kind "type"|"rpc"|"field"
---@field score? number

---@return understand.ProtoMatch[]
function M.search(root, word)
  local names = M.proto_names(word)
  local types, fields = alternation(names.types), alternation(names.fields)
  local patterns = {
    type = [[^\s*(message|enum|service)\s+]] .. types .. [[\b]],
    rpc = [[^\s*rpc\s+]] .. types .. [[\s*\(]],
    field = [[^\s*(repeated\s+|optional\s+)?[\w.]+(\s*<[^>]*>)?\s+]] .. fields .. [[\s*=\s*\d+]],
    enum_value = [[^\s*]] .. alternation({ word }) .. [[\s*=\s*-?\d+\s*[;\[]],
  }
  local matches, jobs = {}, {}
  -- Listing protos through git skips walking target/ and node_modules (~5x faster than rg -g).
  -- Tracked files only: --others walks the whole worktree (0.5s in the monorepo).
  local listed = vim.system({ "git", "ls-files", "--", "*.proto" }, { cwd = root, text = true }):wait()
  local files = listed.code == 0 and vim.split(listed.stdout, "\n", { trimempty = true }) or { "-g", "*.proto", "." }
  if #files == 0 then
    return {}
  end
  for kind, pattern in pairs(patterns) do
    jobs[kind] = vim.system(
      vim.list_extend({ "rg", "--no-heading", "--with-filename", "--line-number", "--column", "-e", pattern }, files),
      { cwd = root, text = true }
    )
  end
  for kind, job in pairs(jobs) do
    local res = job:wait()
    for _, line in ipairs(vim.split(res.stdout or "", "\n", { trimempty = true })) do
      local file, lnum, col, text = line:match("^(.-):(%d+):(%d+):(.*)$")
      if file then
        table.insert(matches, {
          file = vim.fs.normalize(root .. "/" .. file:gsub("^%./", "")),
          lnum = tonumber(lnum),
          col = tonumber(col) - 1,
          text = vim.trim(text),
          kind = kind == "enum_value" and "field" or kind,
        })
      end
    end
  end
  return matches
end

-- Ranks matches by how well their proto file explains the generated code.
---@param matches understand.ProtoMatch[]
---@param generated? { pkg?: string, file?: string }
function M.rank(matches, generated)
  local pkgs = {}
  local function proto_pkgs(file)
    if not pkgs[file] then
      local head = read_head(file, 60)
      local p = { package_of(head) }
      for _, l in ipairs(head) do
        local jp = l:match('^%s*option%s+java_package%s*=%s*"([^"]+)"')
        if jp then
          table.insert(p, jp)
        end
      end
      pkgs[file] = p
    end
    return pkgs[file]
  end
  local kind_score = { type = 3, rpc = 2, field = 1 }
  for _, m in ipairs(matches) do
    m.score = kind_score[m.kind]
    if generated and generated.pkg then
      for _, p in ipairs(proto_pkgs(m.file)) do
        if generated.pkg:find(p, 1, true) then
          m.score = m.score + 10
          break
        end
      end
    end
  end
  table.sort(matches, function(a, b)
    if a.score ~= b.score then
      return a.score > b.score
    end
    return a.file < b.file or (a.file == b.file and a.lnum < b.lnum)
  end)
  -- Keep only the strongest tier: an exact package match makes weaker hits noise.
  local best = matches[1] and matches[1].score
  return vim.tbl_filter(function(m)
    return best - m.score < 10
  end, matches)
end

local function definition_location(buf)
  local clients = vim.lsp.get_clients({ bufnr = buf, method = "textDocument/definition" })
  if #clients == 0 then
    return nil
  end
  local params = vim.lsp.util.make_position_params(0, clients[1].offset_encoding)
  local res = vim.lsp.buf_request_sync(buf, "textDocument/definition", params, 5000) or {}
  for _, r in pairs(res) do
    local loc = r.result and (vim.islist(r.result) and r.result[1] or r.result)
    if loc and (loc.uri or loc.targetUri) then
      return vim.uri_to_fname(loc.uri or loc.targetUri)
    end
  end
  return false
end

local function show(matches, title)
  if #matches == 1 then
    local m = matches[1]
    vim.cmd("normal! m'")
    vim.cmd.edit(vim.fn.fnameescape(m.file))
    vim.api.nvim_win_set_cursor(0, { m.lnum, m.col })
    vim.cmd("normal! zz")
    return
  end
  Snacks.picker.pick({
    title = title,
    items = vim.tbl_map(function(m)
      return { text = m.text .. " " .. m.file, file = m.file, pos = { m.lnum, m.col }, line = m.text }
    end, matches),
    format = "file",
  })
end

-- From generated code (or code using it) to the .proto definition.
---@param word? string defaults to the word under the cursor
function M.goto_proto(word)
  local buf = vim.api.nvim_get_current_buf()
  word = word or vim.fn.expand("<cword>")
  if word == "" then
    return
  end
  local root = vim.fs.root(buf, ".git") or vim.fn.getcwd()

  local generated
  local here = vim.api.nvim_buf_get_lines(buf, 0, 40, false)
  if is_generated(here) then
    generated = { pkg = package_of(here), file = vim.api.nvim_buf_get_name(buf) }
  else
    local def = definition_location(buf)
    if def then
      local head = read_head(def, 40)
      if not is_generated(head) then
        vim.notify(
          ("%s is defined in %s, which isn't generated from a .proto"):format(word, vim.fn.fnamemodify(def, ":~:.")),
          vim.log.levels.WARN,
          { title = "Proto" }
        )
        return
      end
      generated = { pkg = package_of(head), file = def }
    end
  end

  local matches = M.rank(M.search(root, word), generated)
  if #matches == 0 then
    vim.notify(("No .proto definition found for %s"):format(word), vim.log.levels.WARN, { title = "Proto" })
    return
  end
  show(matches, "Proto: " .. word)
end

local function camel(s)
  return (s:gsub("_(%w)", function(c)
    return c:upper()
  end))
end

--- Names that generated Scala/Java code uses for the proto symbol `word` declared on `line`.
function M.usage_names(word, line)
  local names
  if line:match("^%s*rpc%s+" .. word) then
    names = { word, word:sub(1, 1):lower() .. word:sub(2) }
  elseif line:match("^%s*[%w_]+%s*=%s*%-?%d") then -- enum value
    names = { word }
  elseif line:match("=%s*%d+") and word:match("^[%l_%d]+$") then -- field
    local c = camel(word)
    names = { c, "with" .. pascal(c), "get" .. pascal(c), "set" .. pascal(c), word }
  else
    names = { word }
  end
  return vim.fn.uniq(vim.fn.sort(names))
end

-- From a .proto definition to the protos and Scala/Java code that use it (or what's generated
-- from it).
function M.usages()
  local word = vim.fn.expand("<cword>")
  require("search.zoekt").grep({
    title = "Usages of " .. word,
    search = [[\b]] .. alternation(M.usage_names(word, vim.api.nvim_get_current_line())) .. [[\b]],
    terms = [[case:yes f:\.(scala|java|sbt|proto)$]],
    glob = { "*.scala", "*.java", "*.sbt", "*.proto" },
    live = false,
    cwd = vim.fs.root(0, ".git") or vim.fn.getcwd(),
  })
end

return M
